//! Vendor libraries (docs/vendor-libraries-design-plan.md, decision 4): the
//! declarations of each library are Emerald source that joins the prelude only
//! when a program names one of its types, so a program that never draws pays
//! nothing for the graphics library. The list of libraries is generated by
//! `build.zig` from `vendor/libraries.zig`.
const std = @import("std");
const registry = @import("vendor_registry");
const Project = @import("Project.zig");

pub const Library = registry.Library;
pub const libraries = registry.libraries;

/// Which libraries are in play. Always at least one bit, so the type exists
/// when there are no libraries.
pub const Set = std.StaticBitSet(@max(libraries.len, 1));

/// Test-only libraries (`ships = false`) take part only when this is set, which
/// the conformance suite does. A release program cannot name them.
pub var test_libraries = false;

fn available(library: Library) bool {
    return library.ships or test_libraries;
}

/// The libraries whose names the program's own files write. A name in a comment
/// or a string counts too: loading a library that is not used does no harm, and
/// a missed one would be an error.
pub fn named(files: []const Project.File) Set {
    var found: Set = .empty;
    for (libraries, 0..) |library, index| {
        if (!available(library)) continue;
        for (files) |file| {
            if (std.mem.eql(u8, file.namespace, Project.builtin_namespace)) continue;
            if (writes(file.source.text, library)) {
                found.set(index);
                break;
            }
        }
    }
    return found;
}

fn writes(text: []const u8, library: Library) bool {
    for (library.names) |name| {
        var from: usize = 0;
        while (std.mem.indexOfPos(u8, text, from, name)) |at| : (from = at + name.len) {
            const before_ok = at == 0 or !isIdentifierByte(text[at - 1]);
            const end = at + name.len;
            const after_ok = end >= text.len or !isIdentifierByte(text[end]);
            if (before_ok and after_ok) return true;
        }
    }
    return false;
}

fn isIdentifierByte(byte: u8) bool {
    return std.ascii.isAlphanumeric(byte) or byte == '_';
}

/// The prelude's text with each named library's declarations after it, or null
/// when none is named and the prelude's prebuilt syntax tree serves.
pub fn extendedPrelude(gpa: std.mem.Allocator, prelude_text: []const u8, set: Set) std.mem.Allocator.Error!?[]u8 {
    if (set.count() == 0) return null;
    var text: std.ArrayList(u8) = .empty;
    errdefer text.deinit(gpa);
    try text.appendSlice(gpa, prelude_text);
    for (libraries, 0..) |library, index| {
        if (!set.isSet(index)) continue;
        try text.append(gpa, '\n');
        try text.appendSlice(gpa, library.source);
    }
    return try text.toOwnedSlice(gpa);
}

/// The library whose type is named by a prelude key such as
/// `Emerald.Selftest::_add`, with the entry name its module exports
/// (`Selftest::_add`).
pub fn libraryOfNative(key: []const u8, namespace: []const u8) ?struct { index: usize, entry: []const u8 } {
    if (key.len <= namespace.len + 1 or !std.mem.startsWith(u8, key, namespace) or key[namespace.len] != '.') return null;
    const entry = key[namespace.len + 1 ..];
    const type_end = std.mem.indexOf(u8, entry, "::_") orelse return null;
    const type_name = entry[0..type_end];
    for (libraries, 0..) |library, index| {
        for (library.names) |name| {
            if (std.mem.eql(u8, name, type_name)) return .{ .index = index, .entry = entry };
        }
    }
    return null;
}
